#!/usr/bin/env python3
from pathlib import Path
import base64, zlib, shutil, subprocess, sys
from datetime import datetime

UI = """"""
CSS = """"""
START = "/* AV_V2_0_6_MASTER_FIX_START */"
END = "/* AV_V2_0_6_MASTER_FIX_END */"

def unpack(x):
    return zlib.decompress(base64.b64decode(x)).decode("utf-8")

root=Path.cwd()
ui=root/"app/dashboard/ui.tsx"
css=root/"app/globals.css"
if not ui.exists() or not css.exists() or not (root/"package.json").exists():
    print("Run this from the coach-hours-v1 project root (same folder as package.json).")
    sys.exit(1)

stamp=datetime.now().strftime("%Y%m%d-%H%M%S")
backup=root/".av-backups"/f"pre-v2.0.6-{stamp}"
(backup/"app/dashboard").mkdir(parents=True,exist_ok=True)
shutil.copy2(ui,backup/"app/dashboard/ui.tsx")
shutil.copy2(css,backup/"app/globals.css")
print("Backup:",backup)

ui.write_text(unpack(UI),encoding="utf-8")
existing=css.read_text(encoding="utf-8")
if START in existing and END in existing:
    existing=existing.split(START,1)[0].rstrip()+"\n"+existing.split(END,1)[1].lstrip()
css.write_text(existing.rstrip()+"\n\n"+START+"\n"+unpack(CSS).strip()+"\n"+END+"\n",encoding="utf-8")

print("Installed v2.0.6 master timetable fix.")
print("Running production build...")
r=subprocess.run(["npm","run","build"],cwd=root)
if r.returncode:
    print("BUILD FAILED. Nothing was pushed. Backup is at",backup)
    sys.exit(r.returncode)
print("BUILD PASSED.")

if "--deploy" in sys.argv:
    subprocess.run(["git","add","app/dashboard/ui.tsx","app/globals.css"],cwd=root,check=True)
    diff=subprocess.run(["git","diff","--cached","--quiet"],cwd=root)
    if diff.returncode:
        subprocess.run(["git","commit","-m","Release v2.0.6 master timetable fix"],cwd=root,check=True)
        subprocess.run(["git","push","origin","main"],cwd=root,check=True)
        print("Pushed to GitHub. Wait for Vercel Ready.")
    else:
        print("No changes to commit.")
else:
    print('Deploy with: git add app/dashboard/ui.tsx app/globals.css && git commit -m "Release v2.0.6 master timetable fix" && git push origin main')
